template <typename UnionPtrType>
TextSuggestionCandidatePtr TextSuggestionCandidate::Clone() const {
  // Use UnionPtrType to prevent the compiler from trying to compile this
  // without being asked.
  UnionPtrType rv(New());
  switch (tag_) {
    case Tag::MULTI_WORD:
      rv->set_multi_word(mojo::Clone(*data_.multi_word));
      break;
  }
  return rv;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, TextSuggestionCandidate>::value>::type*>
bool TextSuggestionCandidate::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::MULTI_WORD:
      return mojo::Equals(*(data_.multi_word), *(other.data_.multi_word));
  }

  return false;
}
